import sys

def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()

if __name__ == "__main__":
    if len(sys.argv) != 2:
        raise SystemExit("Usage: python hash_file.py <file>")
    p = Path(sys.argv[1])
    if not p.is_file():
        raise SystemExit(f"Not a file: {p}")
    print(sha256_file(p))

