#!/usr/bin/env python3
"""Lab-safe Cybercrime Investigation Case Ledger and Timeline Reporter."""

import argparse, csv, hashlib, json, sqlite3
from datetime import datetime, timezone
from pathlib import Path

SCHEMA = """
CREATE TABLE IF NOT EXISTS evidence(
 id INTEGER PRIMARY KEY,
 evidence_id TEXT UNIQUE NOT NULL,
 path TEXT NOT NULL,
 size INTEGER NOT NULL,
 sha256 TEXT NOT NULL,
 received_at TEXT NOT NULL,
 notes TEXT
);
CREATE TABLE IF NOT EXISTS events(
 id INTEGER PRIMARY KEY,
 timestamp TEXT NOT NULL,
 source TEXT NOT NULL,
 event TEXT NOT NULL,
 subject TEXT,
 details TEXT
);
"""

def sha256_file(path):
    h=hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda:f.read(1024*1024), b""):
            h.update(chunk)
    return h.hexdigest()

def init(db):
    with sqlite3.connect(db) as con:
        con.executescript(SCHEMA)

def add_evidence(db, evidence_id, path, received_at, notes):
    p=Path(path)
    if not p.is_file(): raise FileNotFoundError(p)
    digest=sha256_file(p)
    with sqlite3.connect(db) as con:
        con.execute(
            "INSERT INTO evidence(evidence_id,path,size,sha256,received_at,notes) VALUES(?,?,?,?,?,?)",
            (evidence_id,str(p),p.stat().st_size,digest,received_at,notes)
        )

def import_events(db, csv_path):
    n=0
    with open(csv_path,newline="",encoding="utf-8") as f, sqlite3.connect(db) as con:
        for row in csv.DictReader(f):
            datetime.fromisoformat(row["timestamp"].replace("Z","+00:00"))
            con.execute(
                "INSERT INTO events(timestamp,source,event,subject,details) VALUES(?,?,?,?,?)",
                (row["timestamp"],row["source"],row["event"],row.get("subject",""),row.get("details",""))
            )
            n+=1
    return n

def report(db, output, case_id):
    with sqlite3.connect(db) as con:
        evidence=con.execute(
            "SELECT evidence_id,path,size,sha256,received_at,notes FROM evidence ORDER BY id"
        ).fetchall()
        events=con.execute(
            "SELECT timestamp,source,event,subject,details FROM events ORDER BY timestamp,id"
        ).fetchall()
    timeline=[]
    for ts,src,ev,sub,det in events:
        dt=datetime.fromisoformat(ts.replace("Z","+00:00"))
        timeline.append({
            "timestamp_original":ts,
            "timestamp_utc":dt.astimezone(timezone.utc).isoformat(),
            "source":src,"event":ev,"subject":sub,"details":det
        })
    data={
      "case_id":case_id,
      "generated_at":datetime.now(timezone.utc).isoformat(),
      "evidence":[
        {"evidence_id":e,"path":p,"size":s,"sha256":h,"received_at":r,"notes":n}
        for e,p,s,h,r,n in evidence
      ],
      "timeline":timeline,
      "limitations":[
        "The dataset is examiner-created or synthetic.",
        "A hash verifies consistency of compared bytes; it does not prove authorship or guilt.",
        "Timeline proximity does not by itself prove causation or attribution.",
        "Legal conclusions require jurisdiction-specific authority and qualified legal review."
      ]
    }
    Path(output).write_text(json.dumps(data,indent=2),encoding="utf-8")

def main():
    ap=argparse.ArgumentParser()
    sp=ap.add_subparsers(dest="cmd",required=True)
    p=sp.add_parser("init"); p.add_argument("db")
    p=sp.add_parser("add-evidence"); p.add_argument("db"); p.add_argument("evidence_id"); p.add_argument("path"); p.add_argument("--received-at",required=True); p.add_argument("--notes",default="")
    p=sp.add_parser("import-events"); p.add_argument("db"); p.add_argument("csv")
    p=sp.add_parser("report"); p.add_argument("db"); p.add_argument("output"); p.add_argument("--case-id",required=True)
    a=ap.parse_args()
    if a.cmd=="init": init(a.db)
    elif a.cmd=="add-evidence": add_evidence(a.db,a.evidence_id,a.path,a.received_at,a.notes)
    elif a.cmd=="import-events": print(import_events(a.db,a.csv))
    elif a.cmd=="report": report(a.db,a.output,a.case_id)

if __name__=="__main__":
    main()
